CREATE TABLE activity(id INTEGER PRIMARY KEY AUTOINCREMENT,contact_id TEXT NOT NULL,actor TEXT NOT NULL,kind TEXT NOT NULL,note TEXT DEFAULT '',channel TEXT DEFAULT '',verified INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE aliases(id INTEGER PRIMARY KEY AUTOINCREMENT,contact_id TEXT NOT NULL,kind TEXT NOT NULL,value TEXT NOT NULL,UNIQUE(contact_id,kind,value));
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT DEFAULT '',before_json TEXT DEFAULT '',after_json TEXT DEFAULT '',occurred_at TEXT NOT NULL);
CREATE TABLE contacts(id TEXT PRIMARY KEY,first_name TEXT DEFAULT '',last_name TEXT DEFAULT '',full_name TEXT NOT NULL,job_title TEXT DEFAULT '',company TEXT DEFAULT '',industry TEXT DEFAULT '',category TEXT DEFAULT 'Investor / Other',email TEXT DEFAULT '',additional_email TEXT DEFAULT '',phone TEXT DEFAULT '',country TEXT DEFAULT '',city TEXT DEFAULT '',linkedin TEXT DEFAULT '',website TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'Imported / Unreviewed', owner TEXT DEFAULT '',last_contact TEXT DEFAULT '',next_followup TEXT DEFAULT '',membership_status TEXT DEFAULT 'Unknown',membership_tier TEXT DEFAULT '',app_registration_date TEXT DEFAULT '',approval_status TEXT DEFAULT 'Unknown',subscription_date TEXT DEFAULT '',renewal_date TEXT DEFAULT '',annual_value REAL DEFAULT 0,marketing_permission TEXT DEFAULT 'Unknown',lawful_basis TEXT DEFAULT 'Not assessed',eligible_for_outreach INTEGER DEFAULT 0,do_not_contact INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE duplicate_candidates(id INTEGER PRIMARY KEY AUTOINCREMENT,contact_id TEXT NOT NULL,other_contact_id TEXT NOT NULL,reason TEXT NOT NULL,score REAL NOT NULL,decision TEXT DEFAULT 'Pending',UNIQUE(contact_id,other_contact_id));
CREATE TABLE import_batches(id INTEGER PRIMARY KEY AUTOINCREMENT,filename TEXT,sheet TEXT,raw_rows INTEGER,contact_rows INTEGER,organization_rows INTEGER,merged_rows INTEGER,skipped_rows INTEGER,sha256 TEXT,created_at TEXT);
CREATE TABLE merge_log(id INTEGER PRIMARY KEY AUTOINCREMENT,retained_id TEXT,merged_id TEXT,reason TEXT,backup_json_z BLOB,occurred_at TEXT,actor TEXT);
CREATE TABLE organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT DEFAULT '',website TEXT DEFAULT '',email TEXT DEFAULT '',location TEXT DEFAULT '',country TEXT DEFAULT '',type TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE settings(k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE TABLE source_rows(id INTEGER PRIMARY KEY AUTOINCREMENT,source_file TEXT NOT NULL,sheet TEXT NOT NULL,row_number INTEGER NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,raw_json_z BLOB NOT NULL,imported_at TEXT NOT NULL);
CREATE TABLE subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,contact_id TEXT NOT NULL,tier TEXT,amount REAL NOT NULL,commission REAL NOT NULL,verification_ref TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'Pending',salesperson TEXT,paid_at TEXT);
CREATE TABLE suppression(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,value TEXT,reason TEXT,created_at TEXT,UNIQUE(kind,value));
CREATE TABLE tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,contact_id TEXT NOT NULL,assignee TEXT DEFAULT '',label TEXT NOT NULL,due_at TEXT NOT NULL,priority TEXT DEFAULT 'Normal',state TEXT DEFAULT 'Open',created_at TEXT NOT NULL);
CREATE TABLE team(username TEXT PRIMARY KEY,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'Sales Executive',active INTEGER DEFAULT 1);
CREATE INDEX idx_activity_contact ON activity(contact_id,created_at);
CREATE INDEX idx_alias_lookup ON aliases(kind,value);
CREATE INDEX idx_contact_company ON contacts(company COLLATE NOCASE);
CREATE INDEX idx_contact_followup ON contacts(next_followup);
CREATE INDEX idx_contact_name ON contacts(full_name COLLATE NOCASE);
CREATE INDEX idx_contact_owner ON contacts(owner);
CREATE INDEX idx_contact_status ON contacts(status);
CREATE INDEX idx_orgname ON organizations(name COLLATE NOCASE);
CREATE INDEX idx_sources_entity ON source_rows(entity_type,entity_id);
CREATE INDEX idx_sources_file ON source_rows(source_file);
CREATE INDEX idx_tasks_due ON tasks(due_at,state);
